        }

        .goog-te-spinner-animation {
            background: #ccc;
            display: flex;
            align-items: center;
            justify-content: center;
            width: 104px;
            height: 104px;
            border-radius: 50px;
            background: #fff url(data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciLz4=) 50% 50% no-repeat;
            transition: all 0.6s ease-in-out;
            transform: scale(0.4);
            opacity: 0
        }

        .goog-te-spinner-animation-show {
            transform: scale(0.5);
            opacity: 1
